76	    /**
77	     * Maximum number of owners a single city may hold. A create request whose city already contains
78	     * this many owners is rejected as a conflict.
79	     */
80	    static final int MAX_OWNERS_PER_CITY = 50;
81	
82	    /**
83	     * Maximum number of owners that may be registered on a single day. A create request whose
84	     * registration date already holds this many owners is rejected with 429 Too Many Requests.
85	     */
86	    static final int MAX_OWNERS_PER_DAY = 100;
87	
88	    /**
89	     * Number of owners that may be registered on the current business day before a create/read
90	     * response flags {@code bulkSignupWarning}. Once more than this many owners exist for the day,
91	     * the warning is raised.
92	     */
93	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
94	
95	    /**
96	     * Number of owners a city may hold before a create/read response flags {@code capacityWarning}.
97	     * Once a city holds at least this many owners (but has not yet reached {@link
98	     * #MAX_OWNERS_PER_CITY}), the warning is raised to signal it is approaching the hard limit.
99	     */
100	    static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
101	
