157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
160	        if (idempotencyKey != null) {
161	            Optional<OwnerDto> existing = idempotencyKeyStore.findOwnerId(idempotencyKey)
162	                .map(this.clinicService::findOwnerById)
163	                .map(this::toOwnerDtoWithWarnings);
164	            if (existing.isPresent()) {
165	                return new ResponseEntity<>(existing.get(), HttpStatus.OK);
166	            }
167	        }
168	        resolveAddress(ownerFieldsDto);
169	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
170	        if (!missingFields.isEmpty()) {
171	            throw new MissingOwnerFieldsException(missingFields);
172	        }
173	        HttpHeaders headers = new HttpHeaders();
174	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
175	        if (!PostcodeValidator.isValidForCity(owner.getCity(), owner.getPostcode())) {
176	            throw new InvalidPostcodeException(owner.getPostcode(), owner.getCity());
177	        }
178	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
179	            throw new CityCapacityExceededException(owner.getCity());
180	        }
181	        if (RegistrationDatePolicy.isAfterServerDate(owner.getRegistrationDate())) {
182	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
183	        }
184	        LocalDate registrationDate = RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate());
185	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
186	            throw new DailyOwnerLimitExceededException(registrationDate);
187	        }
188	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
189	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
190	        if (DisposableEmailValidator.isDisposable(owner.getEmail())) {
191	            throw new DisposableEmailException(owner.getEmail());
192	        }
193	        // The household is keyed on (last name, postcode): the id is deterministic, so owners with
194	        // the same last name and postcode share it automatically.
195	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
196	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
197	        owner.setDeclaredHouseholdMember(declaredHouseholdMember);
198	        // An owner whose identity key matches an existing owner is the same person and is rejected,
199	        // unless it declares shared membership — in which case it is created as a known household
200	        // member. Household members with different telephones have distinct identity keys and are
201	        // not duplicates.
202	        if (!declaredHouseholdMember && this.clinicService.isIdentityDuplicate(owner)) {
203	            throw new DuplicateIdentityException(owner.getIdentityKey());
204	        }
205	        this.clinicService.saveOwner(owner);
206	        this.ownerAuditor.ownerCreated(owner);
207	        this.welcomeNotifier.welcome(owner);
208	        if (idempotencyKey != null) {
209	            this.idempotencyKeyStore.remember(idempotencyKey, owner.getId());
210	        }
211	        OwnerDto ownerDto = toOwnerDtoWithWarnings(owner);
212	        headers.setLocation(UriComponentsBuilder.newInstance()
213	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
214	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
215	    }
