239	    /**
240	     * Map an owner to its DTO and stamp the advisory warning flags derived from the current state of
241	     * the clinic ({@code bulkSignupWarning} and {@code capacityWarning}).
242	     */
243	    private OwnerDto toOwnerDtoWithWarnings(Owner owner) {
244	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
245	        stampBulkSignupWarning(ownerDto);
246	        stampCapacityWarning(ownerDto, owner);
247	        stampRiskFlag(ownerDto, owner);
248	        return ownerDto;
249	    }
250	
251	    /**
252	     * Stamp {@code bulkSignupWarning}, which reflects whether more than {@link
253	     * #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been registered on the current business day.
254	     */
255	    private void stampBulkSignupWarning(OwnerDto ownerDto) {
256	        LocalDate today = RegistrationDatePolicy.effectiveDate(null);
257	        ownerDto.setBulkSignupWarning(
258	            this.clinicService.countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
259	    }
260	
261	    /**
262	     * Stamp {@code capacityWarning}, which reflects whether the owner's city already holds between
263	     * {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #MAX_OWNERS_PER_CITY} minus one owners,
264	     * signalling that it is approaching the per-city capacity limit.
265	     */
266	    private void stampCapacityWarning(OwnerDto ownerDto, Owner owner) {
267	        long cityOwners = this.clinicService.countOwnersByCity(owner.getCity());
268	        ownerDto.setCapacityWarning(
269	            cityOwners >= CITY_CAPACITY_WARNING_THRESHOLD && cityOwners < MAX_OWNERS_PER_CITY);
270	    }
271	
272	    /**
273	     * Stamp {@code riskFlag}, which flags an owner for manual risk review when any single risk signal
274	     * holds: the owner is a possible duplicate, its email domain is disposable-adjacent, or its city
275	     * is at or over its soft capacity of {@link #CITY_CAPACITY_WARNING_THRESHOLD} owners.
276	     */
277	    private void stampRiskFlag(OwnerDto ownerDto, Owner owner) {
278	        boolean possibleDuplicate = Boolean.TRUE.equals(owner.getPossibleDuplicate());
279	        boolean disposableAdjacent = DisposableEmailValidator.isDisposableAdjacent(owner.getEmail());
280	        boolean cityOverSoftCapacity =
281	            this.clinicService.countOwnersByCity(owner.getCity()) >= CITY_CAPACITY_WARNING_THRESHOLD;
282	        ownerDto.setRiskFlag(possibleDuplicate || disposableAdjacent || cityOverSoftCapacity);
283	    }
