285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
288	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
289	        if (currentOwner == null) {
290	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
291	        }
292	        currentOwner.setAddress(ownerFieldsDto.getAddress());
293	        currentOwner.setCity(ownerFieldsDto.getCity());
294	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
295	        currentOwner.setLastName(ownerFieldsDto.getLastName());
296	        currentOwner.setTelephone(TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
297	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
298	        this.clinicService.saveOwner(currentOwner);
299	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
300	    }
301	
302	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
303	    @Transactional
304	    @Override
305	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
306	        Owner owner = this.clinicService.findOwnerById(ownerId);
307	        if (owner == null) {
308	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
309	        }
310	        this.clinicService.deleteOwner(owner);
311	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
312	    }
