314	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
315	    @Override
316	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
317	        Owner owner = this.clinicService.findOwnerById(ownerId);
318	        if (owner == null) {
319	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
320	        }
321	        HttpHeaders headers = new HttpHeaders();
322	        Pet pet = petMapper.toPet(petFieldsDto);
323	        owner.setId(ownerId);
324	        pet.setOwner(owner);
325	        pet.getType().setName(null);
326	        this.clinicService.savePet(pet);
327	        PetDto petDto = petMapper.toPetDto(pet);
328	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
329	            .buildAndExpand(pet.getId()).toUri());
330	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
331	    }
