351	    @Override
352	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
353	        HttpHeaders headers = new HttpHeaders();
354	        Visit visit = visitMapper.toVisit(visitFieldsDto);
355	        Pet pet = new Pet();
356	        pet.setId(petId);
357	        visit.setPet(pet);
358	        this.clinicService.saveVisit(visit);
359	        VisitDto visitDto = visitMapper.toVisitDto(visit);
360	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
361	            .buildAndExpand(visit.getId()).toUri());
362	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
363	    }
