367	    @Override
368	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
369	        Owner owner = this.clinicService.findOwnerById(ownerId);
370	        if (owner != null) {
371	            Pet pet = owner.getPet(petId);
372	            if (pet != null) {
373	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
374	            }
375	        }
376	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
377	    }
