282	    /**
283	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
284	     * 64-character lower-case SHA-256 hex digest (see {@link org.springframework.samples.petclinic.util.Sha256})
285	     * of the normalized telephone, the lower-cased email (or an empty string when absent) and the
286	     * {@linkplain org.springframework.samples.petclinic.util.Soundex Soundex} code of the last name,
287	     * joined with {@code '|'} and mixed with the {@link IdentityVersion} version tag. Two owners are
288	     * the same person only when their identity keys are equal; because the telephone is part of the
289	     * key, household members with different telephones have different keys.
290	     */
291	    public String getIdentityKey() {
292	        String key = String.join("|",
293	            this.telephone == null ? "" : this.telephone,
294	            this.email == null ? "" : this.email.toLowerCase(Locale.ROOT),
295	            Soundex.encode(getLastName()));
296	        return Sha256.hex(IdentityVersion.mix(key));
297	    }
