299	    /** Tenure, in elapsed fiscal years, at or beyond which an owner earns the tenure membership points. */
300	    private static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;
301	
302	    /** Household size at or above which an owner earns the household membership points. */
303	    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
304	
305	    /**
306	     * The owner's membership points, a score derived from the owner's own
307	     * fields. Starts at {@code 0}, gains {@code 2} when a contact email is on
308	     * file, gains {@code 1} when the owner has no namesakes, gains {@code 2}
309	     * when the owner belongs to a household of {@value #HOUSEHOLD_SIZE_FOR_POINTS}
310	     * or more, and gains {@code 3} when the owner's {@link #getTenureFiscalYears()
311	     * tenure} reaches {@value #TENURE_FISCAL_YEARS_FOR_POINTS} or more elapsed fiscal years.
312	     */
313	    public Integer getMembershipPoints() {
314	        int points = 0;
315	        boolean hasEmail = this.email != null && !this.email.isEmpty();
316	        if (hasEmail) {
317	            points += 2;
318	        }
319	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
320	        if (noNamesakes) {
321	            points += 1;
322	        }
323	        boolean largeHousehold = this.householdSize != null && this.householdSize >= HOUSEHOLD_SIZE_FOR_POINTS;
324	        if (largeHousehold) {
325	            points += 2;
326	        }
327	        Long tenureFiscalYears = getTenureFiscalYears();
328	        if (tenureFiscalYears != null && tenureFiscalYears >= TENURE_FISCAL_YEARS_FOR_POINTS) {
329	            points += 3;
330	        }
331	        return points;
332	    }
333	
334	    /**
335	     * The owner's membership level, a number from 1 to 4 mapped from the owner's
336	     * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
337	     * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
338	     *
339	     * <p>The level is held down to the {@linkplain #getMembershipLevelCap()
340	     * household ceiling} when one applies, so a new owner never outranks its
341	     * household by more than one level.
342	     */
343	    public Integer getMembershipLevel() {
344	        int level = pointsToLevel(getMembershipPoints());
345	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
346	            return this.membershipLevelCap;
347	        }
348	        return level;
349	    }
350	
351	    private static int pointsToLevel(int points) {
352	        if (points <= 1) {
353	            return 1;
354	        }
355	        if (points <= 3) {
356	            return 2;
357	        }
358	        if (points <= 5) {
359	            return 3;
360	        }
361	        return 4;
362	    }
363	
