377	    /**
378	     * The owner's tenure: the number of whole fiscal years elapsed from the
379	     * {@link #registrationDate} to the server's current date — the count of 1 July
380	     * boundaries crossed between them (see {@link FiscalYear}), or {@code null} when no
381	     * registration date is on file. Zero while both dates fall in the same fiscal year,
382	     * and never negative for a registration date that is today or earlier.
383	     */
384	    public Long getTenureFiscalYears() {
385	        if (this.registrationDate == null) {
386	            return null;
387	        }
388	        return FiscalYear.elapsedYears(this.registrationDate, LocalDate.now());
389	    }
