391	    /**
392	     * The owner's marketing segment, formatted {@code '<TIER>_<AREA>'} (see
393	     * {@link OwnerSegment}). The {@code TIER} follows the {@linkplain
394	     * #getMembershipLevel() membership level} and the {@code AREA} follows the
395	     * {@linkplain #getLocality() locality}, so the segment is one of
396	     * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"}
397	     * or {@code "STANDARD_REGIONAL"}.
398	     */
399	    public String getOwnerSegment() {
400	        return OwnerSegment.of(getMembershipLevel(), getLocality());
401	    }
