515	    /**
516	     * Return the Pet with the given name, or null if none found for this Owner.
517	     *
518	     * @param name to test
519	     * @return true if pet name is already in use
520	     */
521	    public Pet getPet(String name, boolean ignoreNew) {
522	        name = name.toLowerCase();
523	        for (Pet pet : getPetsInternal()) {
524	            if (!ignoreNew || !pet.isNew()) {
525	                String compName = pet.getName();
526	                compName = compName.toLowerCase();
527	                if (compName.equals(name)) {
528	                    return pet;
529	                }
530	            }
531	        }
532	        return null;
533	    }
