251	    @Override
252	    @Transactional
253	    public void saveOwner(Owner owner) throws DataAccessException {
254	        if (owner.isNew()) {
255	            if (owner.getMemberId() == null) {
256	                owner.setMemberId(memberIdGenerator.generate(owner));
257	            }
258	            owner.setNamesakeCount(namesakeCounter.count(owner));
259	            owner.setHouseholdSize(householdMemberCounter.count(owner));
260	            owner.setMembershipLevelCap(householdMembershipLevelCeiling.ceilingFor(owner));
261	            // A declared household member is knowingly created into a shared household, so it is not
262	            // a suspected duplicate; otherwise fall back to the soft-duplicate signal.
263	            Owner possibleDuplicate = owner.isDeclaredHouseholdMember()
264	                ? null : possibleDuplicateDetector.findPossibleDuplicate(owner);
265	            owner.setPossibleDuplicate(possibleDuplicate != null);
266	            owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
267	        }
268	        ownerRepository.save(owner);
269	
270	    }
