291	    @Transactional(readOnly = true)
292	    public boolean isIdentityDuplicate(Owner owner) throws DataAccessException {
293	        String identityKey = owner.getIdentityKey();
294	        // The telephone is part of the identity key, so any owner sharing it is found by telephone
295	        // first and then confirmed to share the whole key. Soft-deleted owners are ignored so an
296	        // identity freed up by a deletion no longer blocks a create.
297	        return ownerRepository.findByTelephone(owner.getTelephone()).stream()
298	            .filter(existing -> !existing.isDeleted())
299	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
300	    }
