19	import org.springframework.samples.petclinic.model.CityRegion;
20	import org.springframework.samples.petclinic.model.PostcodeRegion;
21	
22	/**
23	 * Validates an owner's optional postcode against the fixed postcode range of its
24	 * city's region.
25	 *
26	 * <p>The ranges live in {@link PostcodeRegion} and are keyed by the region derived
27	 * from the city via {@link CityRegion}: {@code NSW 2000-2099}, {@code VIC 3000-3099}
28	 * and {@code QLD 4000-4099} (all inclusive). A city whose region has no known range
29	 * (including {@link CityRegion#UNKNOWN}) accepts any postcode. Format (four
30	 * digits) is enforced separately by Bean Validation on the request DTO, so this
31	 * class only checks membership of the region's range.
32	 */
33	public final class PostcodeValidator {
34	
35	    private PostcodeValidator() {
36	    }
37	
38	    /**
39	     * Returns whether the given postcode is acceptable for the given city.
40	     *
41	     * <p>An absent postcode is always acceptable (the field is optional), and a
42	     * city whose region has no known range accepts any postcode. Otherwise the
43	     * postcode must fall within its region's inclusive range.
44	     *
45	     * @param city the owner's city
46	     * @param postcode the submitted postcode, may be {@code null} or blank
47	     * @return {@code true} when the postcode is acceptable for the city
48	     */
49	    public static boolean isValidForCity(String city, String postcode) {
50	        if (postcode == null || postcode.isBlank()) {
51	            return true;
52	        }
53	        String region = CityRegion.regionFor(city);
54	        if (!PostcodeRegion.hasRange(region)) {
55	            return true;
56	        }
57	        // Ranges are disjoint, so the postcode is valid for the city's region
58	        // exactly when its own region matches.
59	        return region.equals(PostcodeRegion.regionFor(postcode));
60	    }
61	}
