21	/**
22	 * Normalizes an owner's telephone number to canonical E.164 form. A leading {@code '+'} and its
23	 * country code are preserved when present; otherwise the default country code {@code +61} is
24	 * assumed and a single leading {@code '0'} is dropped from the national digits. Separators such as
25	 * spaces, dashes and brackets are stripped. The result must carry 8 to 15 digits after the
26	 * {@code '+'}, and for a recognised country code the national number must be exactly as long as
27	 * that country requires ({@code +61} => 9 national digits, {@code +1} => 10). A number that cannot
28	 * form a valid E.164 value is rejected.
29	 */
30	public final class TelephoneNormalizer {
31	
32	    private static final Pattern NON_DIGIT = Pattern.compile("\\D");
33	
34	    private static final String DEFAULT_COUNTRY_CODE = "61";
35	
36	    private static final int MIN_DIGITS = 8;
37	
38	    private static final int MAX_DIGITS = 15;
39	
40	    private TelephoneNormalizer() {
41	    }
42	
43	    /**
44	     * Converts the supplied telephone to its canonical E.164 representation.
45	     *
46	     * @param telephone the raw telephone as submitted
47	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
48	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
49	     */
50	    public static String normalize(String telephone) {
51	        String trimmed = telephone == null ? "" : telephone.trim();
52	        boolean hasCountryCode = trimmed.startsWith("+");
53	        String digits = NON_DIGIT.matcher(trimmed).replaceAll("");
54	
55	        String countryCode;
56	        String national;
57	        if (hasCountryCode) {
58	            countryCode = CountryDialingCodes.matching(digits);
59	            national = countryCode == null ? digits : digits.substring(countryCode.length());
60	        } else {
61	            countryCode = DEFAULT_COUNTRY_CODE;
62	            national = digits.startsWith("0") ? digits.substring(1) : digits;
63	        }
64	
65	        String e164 = "+" + (countryCode == null ? digits : countryCode + national);
66	
67	        int digitCount = e164.length() - 1;
68	        if (digitCount < MIN_DIGITS || digitCount > MAX_DIGITS) {
69	            throw new InvalidTelephoneException(telephone);
70	        }
71	        Integer requiredNationalLength = CountryDialingCodes.nationalLength(countryCode);
72	        if (requiredNationalLength != null && national.length() != requiredNationalLength) {
73	            throw new InvalidTelephoneException(telephone);
74	        }
75	        return e164;
76	    }
77	}
