22	/**
23	 * Checks an owner's email address against a blocklist of disposable-email domains. Owners are
24	 * expected to supply a durable address, so throwaway providers are refused.
25	 */
26	public final class DisposableEmailValidator {
27	
28	    /** The disposable-email domains that are not accepted for an owner. */
29	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
30	        "mailinator.com", "tempmail.com", "guerrillamail.com");
31	
32	    private DisposableEmailValidator() {
33	    }
34	
35	    /**
36	     * Returns whether the supplied email's domain is on the disposable-domain blocklist. The
37	     * comparison is case-insensitive; a {@code null}, blank or address-less value is not blocked.
38	     *
39	     * @param email the email as submitted, possibly {@code null} or blank
40	     * @return {@code true} when the email's domain is blocklisted, {@code false} otherwise
41	     */
42	    public static boolean isDisposable(String email) {
43	        String domain = domainOf(email);
44	        return domain != null && BLOCKED_DOMAINS.contains(domain);
45	    }
46	
47	    /**
48	     * Returns whether the supplied email's domain is <em>disposable-adjacent</em>: a subdomain of a
49	     * blocklisted disposable provider (for example {@code inbox.mailinator.com}) rather than the
50	     * blocked domain itself. Such an address is not refused outright at creation yet still belongs to
51	     * a throwaway provider, so it is worth surfacing as a soft risk signal. The comparison is
52	     * case-insensitive; a {@code null}, blank or address-less value is not adjacent.
53	     *
54	     * @param email the email as submitted, possibly {@code null} or blank
55	     * @return {@code true} when the email's domain is a subdomain of a blocklisted domain
56	     */
57	    public static boolean isDisposableAdjacent(String email) {
58	        String domain = domainOf(email);
59	        if (domain == null) {
60	            return false;
61	        }
62	        return BLOCKED_DOMAINS.stream().anyMatch(blocked -> domain.endsWith("." + blocked));
63	    }
64	
65	    /**
66	     * Extracts the lower-cased domain part of an email, or {@code null} when the value is
67	     * {@code null} or carries no {@code '@'} separator.
68	     */
69	    private static String domainOf(String email) {
70	        if (email == null) {
71	            return null;
72	        }
73	        int at = email.lastIndexOf('@');
74	        if (at < 0) {
75	            return null;
76	        }
77	        return email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
78	    }
79	}
