16	package org.springframework.samples.petclinic.util;
17	
18	import org.springframework.samples.petclinic.model.IdentityVersion;
19	
20	/**
21	 * Derives the stable identifier shared by owners who belong to the same household, i.e. who share a
22	 * last name and postcode. The last name is normalized (case-insensitively, with collapsed
23	 * whitespace) and joined to the postcode with {@code '|'}, then mixed with the {@link IdentityVersion}
24	 * version tag; the identifier is the leading hex characters of the SHA-256 digest of that key. Because
25	 * it is a deterministic digest, every owner with the same last name and postcode computes the same
26	 * value automatically, and it never changes as members join or leave.
27	 */
28	public final class HouseholdIdGenerator {
29	
30	    /** Number of leading hex characters of the digest kept as the identifier. */
31	    private static final int LENGTH = 12;
32	
33	    private HouseholdIdGenerator() {
34	    }
35	
36	    /**
37	     * Produce the household identifier for the given last name and postcode, or {@code null} when
38	     * no postcode is on file (an owner without a postcode belongs to no shared household).
39	     *
40	     * @param lastName the household's last name
41	     * @param postcode the household's postcode
42	     * @return the identifier shared by every owner with this last name and postcode, or
43	     *         {@code null} when the postcode is absent
44	     */
45	    public static String generate(String lastName, String postcode) {
46	        if (postcode == null || postcode.isBlank()) {
47	            return null;
48	        }
49	        String key = IdentityVersion.mix(TextNormalizer.normalizeForComparison(lastName) + '|' + postcode);
50	        return Sha256.hexPrefix(key, LENGTH);
51	    }
52	}
