16	package org.springframework.samples.petclinic.service;
17	
18	import org.springframework.samples.petclinic.model.IdentityVersion;
19	import org.springframework.samples.petclinic.model.Locality;
20	import org.springframework.samples.petclinic.model.MemberId;
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.repository.OwnerRepository;
23	import org.springframework.samples.petclinic.util.FiscalYear;
24	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
25	import org.springframework.stereotype.Component;
26	
27	/**
28	 * Produces the member id assigned to a new {@link Owner}.
29	 *
30	 * <p>The id is the owner's {@link MemberId} identity {@code '<REGION><FY><HASH8><CHK>'}: the region
31	 * derived from the owner's postcode (via {@link Locality}, so it disambiguates cities that share a
32	 * name and falls back to the city table) and then tagged with the {@link IdentityVersion} version
33	 * tag, the two-digit fiscal year of the owner's (effective) registration date, a hash of the owner's
34	 * normalized telephone and last name, and a Luhn check digit (e.g. {@code 'V2NSW273F2A9C1D5'}).
35	 *
36	 * <p>Two owners that share the same region, fiscal year, normalized telephone and last name would
37	 * otherwise be assigned the same identity, so when the computed id collides with an existing
38	 * owner's member id it is made unique by appending {@code '-<n>'} with the smallest {@code n} of 2
39	 * or more that is still free.
40	 */
41	@Component
42	public class MemberIdGenerator {
43	
44	    /** Smallest suffix used to disambiguate a colliding member id. */
45	    private static final int FIRST_SUFFIX = 2;
46	
47	    private final OwnerRepository ownerRepository;
48	
49	    public MemberIdGenerator(OwnerRepository ownerRepository) {
50	        this.ownerRepository = ownerRepository;
51	    }
52	
53	    /**
54	     * Generate a unique member id for the given owner from its region, fiscal year and identity fields.
55	     *
56	     * @param owner the owner being registered
57	     * @return the {@code '<REGION><FY><HASH8><CHK>'} member id, de-duplicated with a {@code '-<n>'}
58	     * suffix when it would collide with an existing owner's id
59	     */
60	    public String generate(Owner owner) {
61	        String region = IdentityVersion.regionCode(Locality.of(owner.getCity(), owner.getPostcode()));
62	        int fiscalYearSegment = FiscalYear.yearSegment(RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate()));
63	        String memberId = MemberId.of(region, fiscalYearSegment, owner.getTelephone(), owner.getLastName());
64	        return deduplicate(memberId);
65	    }
66	
67	    /**
68	     * Return {@code memberId} unchanged when no owner holds it, otherwise the first
69	     * {@code '<memberId>-<n>'} variant (starting at {@code n = 2}) that no owner holds yet.
70	     */
71	    private String deduplicate(String memberId) {
72	        if (!ownerRepository.existsByMemberId(memberId)) {
73	            return memberId;
74	        }
75	        for (int n = FIRST_SUFFIX; ; n++) {
76	            String candidate = memberId + "-" + n;
77	            if (!ownerRepository.existsByMemberId(candidate)) {
78	                return candidate;
79	            }
80	        }
81	    }
82	}
