18	import java.util.Comparator;
19	import java.util.Objects;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.repository.OwnerRepository;
23	import org.springframework.samples.petclinic.util.Soundex;
24	import org.springframework.stereotype.Component;
25	
26	/**
27	 * Detects a soft (non-hard) duplicate for an owner being registered.
28	 *
29	 * <p>An owner is a possible duplicate of an existing owner when they share a postcode and a
30	 * like-sounding last name (compared by {@linkplain Soundex Soundex} code) yet carry a different
31	 * {@linkplain Owner#getIdentityKey() identity key}. A matching identity key is excluded because that
32	 * is the territory of hard-duplicate detection (a 409), not this softer signal; the identity key
33	 * already folds in the telephone, so two owners with the same postcode and last name but different
34	 * telephones surface here rather than being rejected.
35	 */
36	@Component
37	public class PossibleDuplicateDetector {
38	
39	    private final OwnerRepository ownerRepository;
40	
41	    public PossibleDuplicateDetector(OwnerRepository ownerRepository) {
42	        this.ownerRepository = ownerRepository;
43	    }
44	
45	    /**
46	     * Find the existing owner the given owner possibly duplicates, or {@code null}
47	     * when there is none. When several existing owners match, the one with the
48	     * lowest id (the earliest registered) is returned.
49	     *
50	     * @param owner the owner being registered
51	     * @return the matching existing owner, or {@code null} if none
52	     */
53	    public Owner findPossibleDuplicate(Owner owner) {
54	        if (owner.getPostcode() == null) {
55	            return null;
56	        }
57	        String lastNameCode = Soundex.encode(owner.getLastName());
58	        String identityKey = owner.getIdentityKey();
59	        return ownerRepository.findAll().stream()
60	            .filter(other -> !other.isDeleted())
61	            .filter(other -> owner.getPostcode().equals(other.getPostcode()))
62	            .filter(other -> Soundex.encode(other.getLastName()).equals(lastNameCode))
63	            .filter(other -> !Objects.equals(identityKey, other.getIdentityKey()))
64	            .min(Comparator.comparing(Owner::getId))
65	            .orElse(null);
66	    }
67	}
