184	    /**
185	     * Handles {@link MissingOwnerFieldsException} raised when a request to create or update an owner
186	     * omits one or more mandatory fields, returning a 400 Bad Request whose {@code errors} array lists
187	     * the name of each missing field.
188	     *
189	     * @param e The {@link MissingOwnerFieldsException} to be handled
190	     * @param request {@link HttpServletRequest} object referring to the current request.
191	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
192	     */
193	    @ExceptionHandler(MissingOwnerFieldsException.class)
194	    @ResponseBody
195	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
196	        HttpStatus status = HttpStatus.BAD_REQUEST;
197	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
198	        detail.setProperty("errors", e.getFields());
199	        return ResponseEntity.status(status).body(detail);
200	    }
